//! `omfp theme set <file>` (UI-091): sends a CSS file overriding the theme tokens to a daemon's `theme.set`, which
//! pushes it to every window; the windows show it with the `matugen` theme (DMN-240).

use std::path::PathBuf;

use anyhow::Context as _;
use omfp_protocol::Theme;
use omfp_protocol::method::ThemeSet;

use crate::remote::{Connection, DaemonArgs};

/// `omfp theme …`.
#[derive(Debug, Clone, PartialEq, Eq, clap::Subcommand)]
pub enum Command {
    /// Sets the user theme of a daemon from a CSS file (e.g. generated by matugen, see contrib/matugen); windows show
    /// it with `:theme matugen`.
    Set(SetArgs),
}

/// `omfp theme set`.
#[derive(Debug, Clone, PartialEq, Eq, clap::Args)]
pub struct SetArgs {
    /// CSS file overriding `--omfp-*` tokens.
    pub file: PathBuf,
    #[command(flatten)]
    pub daemon: DaemonArgs,
}

/// Runs `omfp theme …`; returns what to print on success.
pub async fn run(command: Command) -> anyhow::Result<String> {
    match command {
        Command::Set(args) => set(args).await,
    }
}

async fn set(args: SetArgs) -> anyhow::Result<String> {
    let css = std::fs::read_to_string(&args.file)
        .with_context(|| format!("cannot read {}", args.file.display()))?;
    let target = args.daemon.target()?;
    let mut connection = Connection::open(&target).await?;
    connection
        .call::<ThemeSet>(Theme { css: Some(css) })
        .await?;
    connection.close().await?;
    Ok(format!(
        "theme set from {} on {}",
        args.file.display(),
        target.url
    ))
}
